// Sample data: FICTIONAL firms for demo only. Replace with a real source (CSV, Sheet, Clay table, CRM export).
const firms = [
  { name: 'Northfield Capital Partners', domain: 'northfieldcap.example', aum_usd_bn: 62, strategy: 'Buyout', sector_focus: 'Healthcare, Software', hq_country: 'US', months_since_fundraise: 5, debt_maturity_12m: true },
  { name: 'Alder Credit Advisors', domain: 'aldercredit.example', aum_usd_bn: 18, strategy: 'Private Credit', sector_focus: 'Industrials', hq_country: 'UK', months_since_fundraise: 9, debt_maturity_12m: true },
  { name: 'Brightwater Growth', domain: 'brightwatergrowth.example', aum_usd_bn: 7, strategy: 'Growth Equity', sector_focus: 'Fintech, SaaS', hq_country: 'US', months_since_fundraise: 22, debt_maturity_12m: false },
  { name: 'Kestrel Ventures', domain: 'kestrelvc.example', aum_usd_bn: 1.2, strategy: 'Venture', sector_focus: 'Consumer', hq_country: 'IN', months_since_fundraise: 30, debt_maturity_12m: false },
  { name: 'Harbor Lane Real Assets', domain: 'harborlane.example', aum_usd_bn: 11, strategy: 'Real Estate', sector_focus: 'Logistics', hq_country: 'SG', months_since_fundraise: 14, debt_maturity_12m: true },
  { name: 'Meridian Buyout Group', domain: 'meridianbuyout.example', aum_usd_bn: 3.5, strategy: 'Buyout', sector_focus: 'Business Services', hq_country: 'DE', months_since_fundraise: 11, debt_maturity_12m: false },
  { name: 'Quill Street Capital', domain: 'quillstreet.example', aum_usd_bn: 0.6, strategy: 'Growth Equity', sector_focus: 'Media', hq_country: 'BR', months_since_fundraise: 40, debt_maturity_12m: false },
  { name: 'Summit Ridge Credit', domain: 'summitridge.example', aum_usd_bn: 29, strategy: 'Private Credit', sector_focus: 'Software, Healthcare', hq_country: 'US', months_since_fundraise: 3, debt_maturity_12m: false },
];
return firms.map(f => ({ json: f }));

// ICP scoring and segmentation. All weights are ASSUMPTIONS: tune them against your own closed-won data.
const CFG = {
  sizeTiers: [ { min: 50, pts: 30, band: 'Mega (50bn+)' }, { min: 10, pts: 22, band: 'Large (10-50bn)' }, { min: 2, pts: 14, band: 'Mid (2-10bn)' }, { min: 0, pts: 6, band: 'Small (<2bn)' } ],
  strategyPts: { 'Buyout': 25, 'Private Credit': 25, 'Growth Equity': 18, 'Real Estate': 12, 'Venture': 8 },
  geoPts: { US: 15, UK: 12, DE: 10, SG: 8 }, geoDefault: 4,
  fundraiseWithinMonths: 12, fundraisePts: 20, debtMaturityPts: 10,
  tierA: 70, tierB: 40,
};
const PLAYS = {
  'Buyout': { committee: ['Deal team (VP / Principal)', 'CFO / Finance', 'Portfolio Operations'], angle: 'Track every financing workflow across live deals in one place' },
  'Private Credit': { committee: ['Origination', 'Portfolio Monitoring', 'Credit Committee support'], angle: 'Lender-side visibility into pipeline, maturities and borrower activity' },
  'Growth Equity': { committee: ['Investment team', 'Finance / Fund Ops'], angle: 'Standardize deal and financing workflow as deal volume scales' },
  'Real Estate': { committee: ['Acquisitions', 'Asset Management', 'Finance'], angle: 'Coordinate financing across multiple assets and lenders' },
  'Venture': { committee: ['Partners', 'Fund Ops'], angle: 'Light-weight workflow tracking for follow-on and bridge financing' },
};
return $input.all().map(({ json: f }) => {
  const size = CFG.sizeTiers.find(t => f.aum_usd_bn >= t.min);
  const sizePts = size.pts;
  const stratPts = CFG.strategyPts[f.strategy] ?? 5;
  const geoPts = CFG.geoPts[f.hq_country] ?? CFG.geoDefault;
  const fundraiseSignal = f.months_since_fundraise <= CFG.fundraiseWithinMonths;
  const signalPts = (fundraiseSignal ? CFG.fundraisePts : 0) + (f.debt_maturity_12m ? CFG.debtMaturityPts : 0);
  const score = Math.min(100, sizePts + stratPts + geoPts + signalPts);
  const tier = score >= CFG.tierA ? 'A' : score >= CFG.tierB ? 'B' : 'C';
  const play = PLAYS[f.strategy] || { committee: ['Investment team'], angle: 'Standardize financing workflow' };
  const signals = [fundraiseSignal ? 'recent fundraise' : null, f.debt_maturity_12m ? 'debt maturity within 12 months' : null].filter(Boolean);
  return { json: { ...f, size_band: size.band, icp_score: score, icp_tier: tier,
    score_breakdown: `size ${sizePts} + strategy ${stratPts} + geo ${geoPts} + signals ${signalPts}`,
    signals: signals.join('; ') || 'none', buying_committee: play.committee.join(' | '), outreach_angle: play.angle } };
});

// Build the HubSpot CRM v3 company payload. Custom properties (icp_score etc.) must exist in HubSpot first (see README).
return $input.all().map(({ json: f }) => ({ json: { ...f, hubspot_body: { properties: {
  name: f.name, domain: f.domain,
  icp_score: String(f.icp_score), icp_tier: f.icp_tier, size_band: f.size_band,
  strategy: f.strategy, outreach_angle: f.outreach_angle, buying_committee: f.buying_committee, signals: f.signals,
} } } }));
